// ─── Shared text primitive ────────────────────────────────────────────────────
function P({
  children,
  style,
}: {
  children: React.ReactNode;
  style?: React.CSSProperties;
}) {
  return (
    <p
      style={{
        fontSize: "clamp(14px, 2.5vw, 16px)",
        color: "#1a1a2e",
        lineHeight: "24px",
        margin: "0",
        letterSpacing: "-0.5px",
        textWrap: "pretty" as React.CSSProperties["textWrap"],
        ...style,
      }}
    >
      {children}
    </p>
  );
}

function ImgText({
  image,
  side = "left",
  imageWidth = "clamp(200px, 28%, 420px)",
  gap = 40,
  imgStyle,
  style,
  children,
}: {
  image: React.ReactNode;
  side?: "left" | "right";
  imageWidth?: string | number;
  gap?: number;
  imgStyle?: React.CSSProperties;
  style?: React.CSSProperties;
  children: React.ReactNode;
}) {
  const w = typeof imageWidth === "number" ? `${imageWidth}px` : imageWidth;
  const cols = side === "left" ? `${w} 1fr` : `1fr ${w}`;
  const imgCol = side === "left" ? 1 : 2;
  const txtCol = side === "left" ? 2 : 1;
  return (
    <div style={{ display: "grid", gridTemplateColumns: cols, gap, ...style }}>
      <div
        style={{
          gridColumn: imgCol,
          gridRow: 1,
          overflow: "hidden",
          minHeight: 0,
          ...imgStyle,
        }}
      >
        {image}
      </div>
      <div style={{ gridColumn: txtCol, gridRow: 1, display: "flex", flexDirection: "column" }}>
        {children}
      </div>
    </div>
  );
}

