function VideoPlayer({ src, style }: { src: string; style?: React.CSSProperties }) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [playing, setPlaying] = useState(false);
  const [hovering, setHovering] = useState(false);

  const togglePlay = () => {
    if (!videoRef.current) return;
    if (playing) {
      videoRef.current.pause();
      setPlaying(false);
    } else {
      videoRef.current.play();
      setPlaying(true);
    }
  };

  // sync state if video ends naturally
  const handleEnded = () => setPlaying(false);

  return (
    <div
      style={{
        position: "relative",
        cursor: "pointer",
        borderRadius: 8,
        overflow: "hidden",
        ...style,
      }}
      onClick={togglePlay}
      onMouseEnter={() => setHovering(true)}
      onMouseLeave={() => setHovering(false)}
    >
      <video
        ref={videoRef}
        src={src}
        onEnded={handleEnded}
        // show native controls only when playing
        controls={playing}
        style={{ width: "100%", display: "block" }}
      />

      {/* Show play button when NOT playing */}
      {!playing && (
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 56,
            height: 56,
            borderRadius: "50%",
            backgroundColor: "rgba(0, 0, 0, 0.6)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              width: 0,
              height: 0,
              borderTop: "10px solid transparent",
              borderBottom: "10px solid transparent",
              borderLeft: "18px solid white",
              marginLeft: 4,
            }}
          />
        </div>
      )}

      {/* Show pause button on hover when playing */}
      {playing && hovering && (
        <div
          onClick={togglePlay}
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 56,
            height: 56,
            borderRadius: "50%",
            backgroundColor: "rgba(0, 0, 0, 0.6)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 6,
          }}
        >
          {/* Pause icon - two bars */}
          <div style={{ display: "flex", gap: 5 }}>
            <div style={{ width: 4, height: 18, backgroundColor: "white", borderRadius: 2 }} />
            <div style={{ width: 4, height: 18, backgroundColor: "white", borderRadius: 2 }} />
          </div>
        </div>
      )}
    </div>
  );
}

