// ─── 3-column pain point / feature card ──────────────────────────────────────
function ThreeCol({
  items,
  style,
}: {
  items: { icon?: React.ReactNode; title: string; desc: string }[];
  style?: React.CSSProperties;
}) {
  return (
    <div style={{ display: "flex", gap: 24, marginTop: 24, ...style }}>
      {items.map(({ icon, title, desc }) => (
        <div key={title} style={{ flex: 1, display: "flex", flexDirection: "column", gap: 12 }}>
          {icon && <div style={{ width: 40, height: 40 }}>{icon}</div>}
          <p style={{ fontWeight: 600, fontSize: "clamp(14px, 2vw, 16px)", color: "#1d1d1d", lineHeight: "22px", margin: 0 }}>{title}</p>
          <p style={{ fontSize: 14, color: "#575352", lineHeight: "22px", margin: 0 }}>{desc}</p>
        </div>
      ))}
    </div>
  );
}

// ─── Image grid (2 or 3 columns) ─────────────────────────────────────────────
function ImageGrid({
  images,
  caption,
  cols = 2,
  height = 240,
}: {
  images: { src?: string; alt: string }[];
  caption?: string;
  cols?: 2 | 3;
  height?: number;
}) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 24 }}>
      <div style={{ display: "grid", gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: 8 }}>
        {images.map(({ src, alt }) => (
          <div
            key={alt}
            style={{
              height,
              borderRadius: 6,
              overflow: "hidden",
              background: "#fef3c7",
              border: "1px solid rgba(26,26,46,0.08)",
            }}
          >
            {src ? (
              <img src={src} alt={alt} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
            ) : (
              <div style={{
                width: "100%", height: "100%",
                background: "linear-gradient(145deg, #fde68a 0%, #fcd34d 100%)",
                display: "flex", alignItems: "center", justifyContent: "center",
                color: "#92400e", fontSize: 11, fontWeight: 600, letterSpacing: "0.5px",
              }}>
                {alt}
              </div>
            )}
          </div>
        ))}
      </div>
      {caption && (
        <p style={{ fontSize: 12, color: "#8d8786", textAlign: "center", margin: 0, letterSpacing: "-0.2px" }}>
          {caption}
        </p>
      )}
    </div>
  );
}

